import unittest
from candidate import monotonic

class TestMonotonic(unittest.TestCase):
    def test_monotonic_increasing(self):
        self.assertTrue(monotonic([1, 2, 3, 4]))

    def test_monotonic_decreasing(self):
        self.assertTrue(monotonic([5, 4, 3, 2]))

    def test_monotonic_mixed_increasing(self):
        self.assertTrue(monotonic([1, 2, 4, 20]))

    def test_monotonic_mixed_decreasing(self):
        self.assertTrue(monotonic([20, 4, 2, 1]))

    def test_non_monotonic(self):
        self.assertFalse(monotonic([1, 20, 4, 10]))

    def test_empty_list(self):
        self.assertTrue(monotonic([]))

    def test_single_element(self):
        self.assertTrue(monotonic([7]))

    def test_constant_list(self):
        self.assertTrue(monotonic([5, 5, 5, 5]))

    def test_negative_numbers_increasing(self):
        self.assertTrue(monotonic([-1, -2, -3]))

    def test_negative_numbers_decreasing(self):
        self.assertTrue(monotonic([-3, -2, -1]))

    def test_mixed_positive_negative(self):
        self.assertTrue(monotonic([-5, -3, 0, 1]))

    def test_mixed_positive_negative_reversed(self):
        self.assertTrue(monotonic([1, 0, -3, -5]))

    def test_invalid_type(self):
        with self.assertRaises(TypeError):
            monotonic("not_a_list")

    def test_none_input(self):
        with self.assertRaises(TypeError):
            monotonic(None)

    def test_list_with_non_numeric_elements(self):
        with self.assertRaises(TypeError):
            monotonic([1, 'a', 3])

    def test_duplicate_elements(self):
        self.assertTrue(monotonic([1, 1, 2, 2]))

    def test_large_list_increasing(self):
        self.assertTrue(monotonic(list(range(1, 1001))))

    def test_large_list_decreasing(self):
        self.assertTrue(monotonic(list(range(1000, 0, -1))))

    def test_large_list_non_monotonic(self):
        self.assertFalse(monotonic([1, 2, 3, 100, 4]))
